    let seconds = interval_mins.checked_mul(60).ok_or_else(|| {
        SeakarrError::Config(format!(
            "schedule.interval_mins is too large; maximum is {}",
            u64::MAX / 60
        ))
    })?;
    Ok(tokio::time::Duration::from_secs(seconds))
}

